  2377                                                  seen_obrace = true;
  2378                                          }
  2379                                          else {
  2380
  2381                                                  if (*p == '{') {
  2382                                                          ucl_chunk_skipc (chunk, p);
  2383                                                          parser->state = UCL_STATE_KEY_OBRACE;
  2384                                                          seen_obrace = true;
  2385                                                  }
  2386                                                  else {
  2387                                                          parser->state = UCL_STATE_KEY;
  2388                                                  }
  2389                                          }
  2390                                  }
