  2393                                          if (parser->state == UCL_STATE_VALUE) {
  2394                                                  obj = ucl_parser_add_container (NULL, parser, true, 0,
  2395                                                                  seen_obrace);
  2396                                          }
  2397                                          else {
  2398                                                  obj = ucl_parser_add_container (NULL, parser, false, 0,
  2399                                                                  seen_obrace);
  2400                                          }
